<script>
 import {keyboardScroll} from "$lib/table-scroll.js";import {connectionLabel} from '$lib/admin-domain';import {formatTime} from '$lib/energy';let {data,compact=false}=$props();let search=$state('');let filtered=$derived(data.nodes.filter(n=>(n.display_name+' '+n.reference+' '+n.location_label).toLowerCase().includes(search.toLowerCase())));const href=n=>data.preview?'/admin-preview?view=nodes':'/admin/nodes/'+n.id;</script>
<section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">YOUR REGISTERED SYSTEMS</span><h2>{compact?'Energy nodes':'Node directory'}</h2></div><label class="admin-search"><span class="sr-only">Search nodes</span><input type="search" bind:value={search} placeholder="Search name or reference"/></label></div><div class="admin-table-scroll" use:keyboardScroll role="region" aria-label="Scrollable data table"><table class="admin-table"><thead><tr><th scope="col">Residence / business</th><th scope="col">Connection</th>{#if !compact}<th scope="col">Community</th><th scope="col">Assigned clients</th>{/if}<th scope="col">Last reading · CAT</th><th scope="col"><span class="sr-only">Open node</span></th></tr></thead><tbody>{#each filtered as node}{@const connection=data.connections.find(c=>c.node_id===node.id)}{@const label=connectionLabel(connection,data.secrets.some(s=>s.node_id===node.id))}<tr><td><a class="admin-table-title" href={href(node)}>{node.display_name}</a><small>{node.reference} · {node.location_label}</small></td><td><span class="admin-status" class:good={label==='Verified'}>{label}</span></td>{#if !compact}<td>{data.communities.find(c=>c.id===node.community_id)?.name||'Not assigned'}</td><td>{data.memberships.filter(m=>m.node_id===node.id).map(m=>data.clients.find(c=>c.id===m.user_id)?.full_name||'Client').join(', ')||'No clients yet'}</td>{/if}<td>{formatTime(data.snapshots.find(s=>s.node_id===node.id)?.reported_at)}</td><td><a class="admin-text-link" href={href(node)}>Manage →</a></td></tr>{/each}{#if !filtered.length}<tr><td colspan={compact?4:6}><div class="admin-empty"><strong>{search?'No matching nodes':'No energy nodes yet'}</strong><p>{search?'Try a different search.':'Register a residence or business to begin.'}</p></div></td></tr>{/if}</tbody></table></div>{#if data.nodes.length===500}<p class="admin-help">Showing the first 500 registered nodes.</p>{/if}</section>
